import fs from 'node:fs';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
const root='C:/Users/arnot/.codex/worktrees/lot2-combat-v5/Outil MJ Warhammer';
const out='C:/Users/arnot/AppData/Local/Temp/lot3-c02-20261011';
const {createStore}=await import(pathToFileURL(root+'/js/core/store.js'));
const {getAllSpellContracts,getContractChoiceOptions}=await import(pathToFileURL(root+'/js/core/v5-spell-contracts.js'));
const {parseSpellDuration}=await import(pathToFileURL(root+'/js/core/v5-magic-effects.js'));
const contracts=getAllSpellContracts();
fs.writeFileSync(out+'/contracts-executed.json',JSON.stringify(contracts,null,2));
const caster={id:'mage',name:'Mage C-02',kind:'PJ',camp:'pj',zone:'active',hp:20,maxHp:30,caracs:{CC:50,CT:50,F:40,E:40,I:50,Ag:50,Dex:50,Int:60,FM:60,Soc:50,M:4},skills:[{name:'Langue (Magick)',total:90},{name:'Focalisation',total:90},{name:'Focalisation (Haute Magie)',total:90},{name:'Calme',total:40},{name:'Résistance',total:40}],traits:[],states:[],equipment:[],armor:{head:2,body:2,arms:2,legs:2},extensions:{v5:{hasMomentum:true,channelling:{type:'winds',sl:0},spellEffects:[]}}};
const ally={...structuredClone(caster),id:'ally',name:'Allié',states:[{name:'Brisé',level:2},{name:'Exténué',level:1},{name:'Frénésie',level:1}]};
const enemy={...structuredClone(caster),id:'enemy',name:'Ennemi',kind:'PNJ',camp:'ennemi',hp:30,traits:[]};
const daemon={...structuredClone(enemy),id:'daemon',traits:['Démoniaque','Instable']};
const undead={...structuredClone(enemy),id:'undead',traits:['Mort-vivant','Éthéré']};
const corpse={...structuredClone(ally),id:'corpse',name:'Mort admissible',hp:0,dead:true,roundsDead:2,states:[]};
const state=s=>JSON.parse(s.getFullJSON());
const participantState=s=>state(s).combat.participants;
const report=[];
for(const c of contracts){
 const e=c.effects||{}; let tid='enemy';
 if(/^vous$/i.test(c.target)||e.special==='transformation-of-kadon')tid='mage';
 if(e.alliesOnly||e.excludeCaster||['hand-of-glory','shield-of-saphery','acceptance-of-fate','time-amok','merciw-monstrous-regiment','twist-of-fate','hunters-moons','timewarp','monstrous-regiment','ox-stands'].includes(e.special)||['Main de Gloire','Bouclier de Saphery','Ironie du Destin','Lunes du Chasseur','Dérèglement temporel','Régiment Monstrueux de Merciw','Le Bœuf Reste Debout'].includes(c.name))tid='ally';
 if(e.special==='daemonbane')tid='daemon';
 if(e.special==='verdant-apotheosis')tid='corpse';
 if(c.name==='Vortex d’Âmes')tid='undead';
 const store=createStore(); await store.ready;
 await store.loadFromJSON({schemaVersion:3,reserve:[],combat:{round:1,currentActorId:'mage',order:['mage','ally','enemy','daemon','undead','corpse'],participants:[caster,ally,enemy,daemon,undead,corpse].map(p=>structuredClone(p))},log:[],diceLines:[],extensions:{v5:{turnIndex:1}}});
 const t=store.listParticipants().find(p=>p.id===tid);
 const base={actorId:'mage',targetIds:[tid],sl:c.cn+2,attributeActive:false};
 const minimal=store.previewSpellExecution(c,base);
 const choices=getContractChoiceOptions(c);
 const duration=parseSpellDuration(c.duration,{caster,target:t});
 const input={...base,fellowshipRoll:20,enduranceRoll:95,resistanceRoll:95,locationRoll:34,roll3d10:15,burnoutRoll:50,beastKey:'wolf',chosenStats:['CC'],direction:'N',willpowerSuccess:true,distanceRoll:10,targetsCrossed:[t],monsterProfile:{name:'Profil synthétique C-02 (non sourcé)',M:6,hp:20,caracs:{CC:50,CT:0,F:60,E:60,I:40,Ag:40,Dex:0,Soc:10},traits:[]},targetTests:{[tid]:{roll:95,resistanceRoll:95,enduranceRoll:95,fellowshipRoll:20,deathDelaySec:30}},...(e.special==='arcane-unforgiving'?{arcaneTargets:{[tid]:{magicItemPresent:false}}}:{}),...(choices.length?{mjChoice:choices[0]}:{}),...(duration.kind==='unknown'?{mjDuration:{amount:5,unit:'minutes'}}:{})};
 const row={id:c.id,name:c.name,input,minimal:{ready:minimal.ready,status:minimal.status,error:minimal.error,missing:minimal.missing},duration,started:new Date().toISOString()};
 try{
  const before=participantState(store);const p=store.previewSpellExecution(c,input);row.preview=p;
  row.previewPure=JSON.stringify(before)===JSON.stringify(participantState(store));
  try{const a=await store.applySpellExecution(c,input);row.applied=true;row.applicationReceipt=a;row.after=participantState(store);
   const loaded=createStore();await loaded.ready;await loaded.loadFromJSON(state(store));row.reloadEqual=JSON.stringify(participantState(loaded))===JSON.stringify(row.after);
   await store.undo();row.undoEqual=JSON.stringify(participantState(store))===JSON.stringify(before);
  }catch(err){row.applied=false;row.applyError=String(err.message);}
 }catch(err){row.error=String(err.stack);}
 report.push(row);
}
fs.writeFileSync(out+'/execution.json',JSON.stringify(report,null,2));
const tally={total:report.length,ready:report.filter(r=>r.preview?.ready).length,applied:report.filter(r=>r.applied).length,pure:report.filter(r=>r.previewPure).length,undoEqual:report.filter(r=>r.undoEqual).length,reloadEqual:report.filter(r=>r.reloadEqual).length};
console.log(JSON.stringify(tally));
for(const r of report.filter(r=>!r.applied||!r.undoEqual||!r.reloadEqual))console.log(JSON.stringify({name:r.name,status:r.preview?.status,error:r.preview?.error,applyError:r.applyError,undo:r.undoEqual,reload:r.reloadEqual}));

