import fs from 'node:fs';import {pathToFileURL} from 'node:url';
const root='C:/Users/arnot/.codex/worktrees/lot2-combat-v5/Outil MJ Warhammer';const out='C:/Users/arnot/AppData/Local/Temp/lot3-c02-20261011';
const {createStore}=await import(pathToFileURL(root+'/js/core/store.js'));const {getSpellContract}=await import(pathToFileURL(root+'/js/core/v5-spell-contracts.js'));
const caster={id:'mage',name:'Mage',kind:'PJ',camp:'pj',zone:'active',hp:20,maxHp:30,caracs:{CC:50,CT:50,F:40,E:40,I:50,Ag:50,Dex:50,Int:60,FM:60,Soc:50,M:4},skills:[{name:'Langue (Magick)',total:90},{name:'Focalisation',total:90},{name:'Athlétisme',total:70}],traits:[],states:[],armor:{head:2,body:2,arms:2,legs:2},extensions:{v5:{hasMomentum:true,channelling:{type:'winds',sl:0}}}};
const baseTarget={...structuredClone(caster),id:'target',name:'Cible',kind:'PNJ',camp:'ennemi',hp:30};
async function probe(label,spell,{target={},input={},after}={}){let s=createStore();await s.ready;const t={...structuredClone(baseTarget),...target};await s.loadFromJSON({schemaVersion:3,reserve:[],combat:{round:1,currentActorId:'mage',order:['mage','target'],participants:[caster,t]},diceLines:[],log:[]});const c=getSpellContract(spell);const tid=c.target==='Vous'?'mage':'target';const i={actorId:'mage',targetIds:[tid],sl:c.cn+2,attributeActive:false,locationRoll:34,...input};const p=s.previewSpellExecution(c,i);let error=null;try{await s.applySpellExecution(c,i)}catch(e){error=e.message}const result={label,spell,input:i,ready:p.ready,error,p,participants:s.listParticipants()};if(after)result.extra=await after(s);return result}
const rows=[];
for (const [sl,armor] of [[0,0],[8,0],[0,2]])rows.push(await probe('Dart SL'+sl+' AP'+armor,'Fléchette',{target:{armor:{head:armor,body:armor,arms:armor,legs:armor}},input:{sl}}));
rows.push(await probe('Dart overcast interdit','Fléchette',{input:{overcastChoices:{damage:1}}}));
rows.push(await probe('Amitié animal non Bestial','Amitié animale',{target:{traits:[],size:'large'}}));
rows.push(await probe('Envol Athlétisme70','Envol'));
rows.push(await probe('Ecoute pas de +DR source','Tendre l\'oreille'));
rows.push(await probe('Linceul pas de +DR source','Linceul d’Invisibilité'));
rows.push(await probe('Ombres suffocation','Ombres Étrangleuses'));
rows.push(await probe('Escalier PA','Escalier en Spirale'));
rows.push(await probe('Visage choix absent','Visage mutable'));
rows.push(await probe('Merciw plafond','Régiment Monstrueux de Merciw',{target:{camp:'pj',caracs:{...caster.caracs,F:85,E:80}}}));
rows.push(await probe('Calme Haine Préjugé','Calme',{target:{camp:'pj',states:[{name:'Haine',key:'hatred',level:1},{name:'Préjugé',key:'prejudice',level:1}]},input:{fellowshipRoll:20}}));
rows.push(await probe('Polir sans palier','Polir et Exalter',{input:{sl:1}}));
fs.writeFileSync(out+'/targeted.json',JSON.stringify(rows,null,2));
for(const r of rows){const t=r.participants.find(p=>p.id===(r.input.targetIds[0]));console.log(JSON.stringify({label:r.label,ready:r.ready,error:r.error,hp:t?.hp,caracs:t?.caracs,armor:t?.armor,traits:t?.traits,testModifiers:t?.extensions?.v5?.testModifiers,states:t?.states,special:t?.extensions?.v5?.specialStates}));}
const execution=JSON.parse(fs.readFileSync(out+'/execution.json','utf8'));
function diff(a,b,path=''){const changes=[];for(const k of new Set([...Object.keys(a||{}),...Object.keys(b||{})])){const x=a?.[k],y=b?.[k];if(JSON.stringify(x)===JSON.stringify(y))continue;if(x&&y&&typeof x==='object'&&typeof y==='object')changes.push(...diff(x,y,path+'.'+k));else changes.push({path:path+'.'+k,before:x,after:y})}return changes}
for(const r of execution.filter(r=>r.reloadEqual===false)){const s=createStore();await s.ready;await s.loadFromJSON({schemaVersion:3,reserve:[],combat:{round:1,currentActorId:'mage',order:r.after.map(p=>p.id),participants:r.after},log:[],diceLines:[]});console.log('RELOAD',r.name,JSON.stringify(diff(r.after,JSON.parse(s.getFullJSON()).combat.participants).slice(0,15)));}
